int firstMissingPositive(vector<int>& a) {
    int n = (int)a.size();
    for (int i = 0; i < n; ++i)
        // keep swapping until a[i] is either out of range or already home
        while (a[i] > 0 && a[i] <= n && a[a[i] - 1] != a[i])
            swap(a[i], a[a[i] - 1]);
    for (int i = 0; i < n; ++i)
        if (a[i] != i + 1) return i + 1;    // first hole
    return n + 1;                            // 1..n all present
}

