def first_missing_positive(a: list[int]) -> int:
    n = len(a)
    for i in range(n):
        # keep swapping until a[i] is out of range or already home
        while 0 < a[i] <= n and a[a[i] - 1] != a[i]:
            target = a[i] - 1
            a[i], a[target] = a[target], a[i]
    for i in range(n):
        if a[i] != i + 1:
            return i + 1        # first hole
    return n + 1                # 1..n all present

