struct ListNode { int val; ListNode* next; ListNode(int v): val(v), next(nullptr) {} };

ListNode* mergeTwo(ListNode* a, ListNode* b) {
    ListNode dummy(0), *tail = &dummy;
    while (a && b) {
        if (a->val <= b->val) { tail->next = a; a = a->next; }   // <= keeps it stable
        else                  { tail->next = b; b = b->next; }
        tail = tail->next;
    }
    tail->next = a ? a : b;
    return dummy.next;
}

ListNode* sortList(ListNode* head) {
    if (!head || !head->next) return head;
    // split at the midpoint: prev trails slow so the list can be cut
    ListNode *slow = head, *fast = head, *prev = nullptr;
    while (fast && fast->next) { prev = slow; slow = slow->next; fast = fast->next->next; }
    prev->next = nullptr;                 // sever into two independent lists
    return mergeTwo(sortList(head), sortList(slow));
}

