int maximumGap(const vector<int>& a) {
    int n = (int)a.size();
    if (n < 2) return 0;
    int lo = *min_element(a.begin(), a.end());
    int hi = *max_element(a.begin(), a.end());
    if (lo == hi) return 0;

    // n-1 buckets over the range => average gap <= bucket width
    int width = max(1, (int)ceil((double)(hi - lo) / (n - 1)));
    int count = (hi - lo) / width + 1;
    vector<int> bmin(count, INT_MAX), bmax(count, INT_MIN);
    for (int x : a) {
        int b = (x - lo) / width;
        bmin[b] = min(bmin[b], x);
        bmax[b] = max(bmax[b], x);
    }
    int best = 0, prevMax = lo;
    for (int b = 0; b < count; ++b) {
        if (bmin[b] == INT_MAX) continue;      // empty bucket: skip
        best = max(best, bmin[b] - prevMax);   // gap spans the empty run
        prevMax = bmax[b];
    }
    return best;
}

void wiggleSort(vector<int>& a) {
    int n = (int)a.size();
    vector<int> s = a;
    nth_element(s.begin(), s.begin() + n / 2, s.end());   // O(n) average
    // Walk both halves from their LARGEST end so equal values land far apart.
    int lo = (n - 1) / 2, hi = n - 1;
    for (int i = 0; i < n; i += 2) a[i] = s[lo--];   // even slots: smaller half
    for (int i = 1; i < n; i += 2) a[i] = s[hi--];   // odd slots: larger half
}

