def wiggle_sort(a: list[int]) -> None:
    n = len(a)
    s = sorted(a)                       # nth_element equivalent for clarity
    # Walk both halves from their LARGEST end so equal values land far apart.
    lo, hi = (n - 1) // 2, n - 1
    for i in range(0, n, 2):
        a[i] = s[lo]; lo -= 1           # even slots: smaller half
    for i in range(1, n, 2):
        a[i] = s[hi]; hi -= 1           # odd slots: larger half

