vector<int> pancakeSort(vector<int> a) {
    vector<int> flips;
    for (int size = (int)a.size(); size > 1; --size) {
        int maxIdx = (int)(max_element(a.begin(), a.begin() + size) - a.begin());
        if (maxIdx == size - 1) continue;                 // already home: 0 flips
        if (maxIdx > 0) {
            reverse(a.begin(), a.begin() + maxIdx + 1);   // flip 1: max to front
            flips.push_back(maxIdx + 1);
        }
        reverse(a.begin(), a.begin() + size);             // flip 2: front to home
        flips.push_back(size);
    }
    return flips;
}

