def pancake_sort(a: list[int]) -> list[int]:
    a = a[:]
    flips = []
    for size in range(len(a), 1, -1):
        max_idx = a.index(max(a[:size]))
        if max_idx == size - 1:
            continue                                   # already home: 0 flips
        if max_idx > 0:
            a[:max_idx + 1] = reversed(a[:max_idx + 1])   # flip 1: max to front
            flips.append(max_idx + 1)
        a[:size] = reversed(a[:size])                  # flip 2: front to home
        flips.append(size)
    return flips

