// Simulates external sort: data too large for RAM is split into sorted runs,
// then merged with a heap holding one element per run.
struct ExternalSort {
    size_t chunkSize;
    vector<vector<int>> runs;          // stand-ins for on-disk files
    long long readOps = 0, writeOps = 0;

    explicit ExternalSort(size_t chunk) : chunkSize(chunk) {}

    // PASS 1: read chunkSize records, sort in RAM, spill as a sorted run
    void makeRuns(const vector<int>& data) {
        for (size_t i = 0; i < data.size(); i += chunkSize) {
            vector<int> run(data.begin() + i,
                            data.begin() + min(i + chunkSize, data.size()));
            readOps += run.size();
            sort(run.begin(), run.end());
            writeOps += run.size();
            runs.push_back(move(run));
        }
    }
    // PASS 2: heap of (value, runIdx, offset); pop smallest, push its successor
    vector<int> mergeRuns() {
        priority_queue<tuple<int,int,int>, vector<tuple<int,int,int>>,
                       greater<>> pq;
        for (int r = 0; r < (int)runs.size(); ++r)
            if (!runs[r].empty()) pq.push({runs[r][0], r, 0});
        vector<int> out;
        while (!pq.empty()) {
            auto [val, r, off] = pq.top(); pq.pop();
            out.push_back(val);
            ++readOps; ++writeOps;
            if (off + 1 < (int)runs[r].size())
                pq.push({runs[r][off + 1], r, off + 1});
        }
        return out;
    }
};
